{
  "name": "graphite-editor-mcp",
  "version": "0.2.0",
  "description": "MCP server exposing a pinned Graphite (graphene-cli) build: deterministic, node-graph procedural graphics rendering for AI agents — data-driven documents in, validated artifacts out.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/ktheunlikedoll/graphite-editor-mcp.git"
  },
  "private": true,
  "type": "module",
  "bin": {
    "graphite-editor-mcp": "dist/src/index.js"
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc --noEmit",
    "test": "vitest run"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.30.0",
    "pngjs": "^7.0.0",
    "zod": "^4.6.5"
  },
  "devDependencies": {
    "@types/node": "^22.20.4",
    "@types/pngjs": "^6.0.5",
    "typescript": "^5.9.3",
    "vitest": "^5.0.1"
  }
}#!/usr/bin/env bash
# Fetch and build the pinned Graphite engine (graphene-cli).
#
# Shallow-fetches the exact pinned upstream commit into engine/Graphite/ and
# builds the debug graphene-cli binary that this MCP server resolves by
# default (<projectRoot>/engine/Graphite/target/debug/graphene-cli).
#
# Reference build facts (commit, binary sha256, toolchain): docs/ENGINE-PIN.md
#
