import { component$, noSerialize, useSignal, useStore, useVisibleTask$, type NoSerialize } from "@builder.io/qwik";
import { css } from "styled-system/css";
import type { DesignTokens } from "~/lib/api-types";
import { LINEN, mountFabric, type FabricHandle, type FabricLook } from "./fabric-gl";

/** Dye the cloth from a persona's tokens: primary warp over a ground-tinted weft. */
export function lookFromTokens(t: DesignTokens, density?: string): FabricLook {
  const c = t.colors;
  return {
    warp: c.primary,
    weft: c.background,
    ground: c.surface,
    dye: 0.92,
    fold: density === "maximalist" || density === "dense" ? 0.85 : 0.65,
    weave: 0.75,
    thread: 2.6,
    scale: 1.5,
    grain: 0.025,
  };
}

interface FabricProps {
  look?: FabricLook;
  class?: string;
  style?: Record<string, string>;
  quality?: number;
  parallax?: number;
  windowPointer?: boolean;
  label?: string;
}

/**
 * A live bolt of cloth. Changing `look` re-dyes it in place (eased, not cut).
 * Falls back to a flat ground colour without WebGL.
 */
export const Fabric = component$<FabricProps>(({ look = LINEN, class: cls, style, quality, parallax, windowPointer, label }) => {
  const canvas = useSignal<HTMLCanvasElement>();
  const handle = useStore<{ h: NoSerialize<FabricHandle> }>({ h: undefined });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    if (!canvas.value) return;
    const h = mountFabric(canvas.value, look, { quality, parallax, windowPointer });
    if (!h) return;
    handle.h = noSerialize(h);
    canvas.value.dataset.ready = "true";
    cleanup(() => h.destroy());
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track }) => {
    const l = track(() => look);
    handle.h?.setLook(l);
  });

  // Without WebGL the CSS weave underneath stays visible: warp over weft,
  // with a diagonal light for folds. The shader fades in over it.
  const weave = `linear-gradient(115deg, rgba(255,255,255,0.18), rgba(0,0,0,0.12) 45%, rgba(255,255,255,0.1) 70%, rgba(0,0,0,0.14)), repeating-linear-gradient(90deg, ${look.warp} 0 ${look.thread}px, transparent ${look.thread}px ${look.thread * 2}px), repeating-linear-gradient(0deg, ${look.weft} 0 ${look.thread}px, ${look.ground} ${look.thread}px ${look.thread * 2}px)`;
  return (
    <div class={`${css({ position: "relative", w: "100%", h: "100%" })} ${cls ?? ""}`} style={{ backgroundImage: weave, transition: "background 0.6s", ...style }}>
      <canvas
        ref={canvas}
        role={label ? "img" : undefined}
        aria-label={label}
        aria-hidden={label ? undefined : "true"}
        class={css({ display: "block", position: "absolute", inset: 0, w: "100%", h: "100%", transition: "opacity 1.2s token(easings.thread)", opacity: 0, "&[data-ready=true]": { opacity: 1 } })}
      />
    </div>
  );
});

/** The page itself: fixed linen behind everything, drifting slightly with scroll. */
export const FabricBackdrop = component$(() => {
  return (
    <div aria-hidden="true" class={css({ position: "fixed", inset: 0, zIndex: -1, pointerEvents: "none" })}>
      <Fabric look={LINEN} quality={0.5} parallax={0.35} windowPointer />
      {/* drafting grid printed on the cloth, fading toward the edges */}
      <div
        class={css({ position: "absolute", inset: 0 })}
        style={{
          backgroundImage:
            "linear-gradient(rgba(28,27,25,0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(28,27,25,0.05) 1px, transparent 1px)",
          backgroundSize: "32px 32px",
          maskImage: "radial-gradient(ellipse 80% 70% at 50% 40%, #000 30%, transparent 90%)",
          WebkitMaskImage: "radial-gradient(ellipse 80% 70% at 50% 40%, #000 30%, transparent 90%)",
        }}
      />
    </div>
  );
});
/**
 * Woven fabric, rendered in a fragment shader.
 *
 * - Plain weave at thread scale: warp and weft can be dyed different
 *   colours, so the cloth shifts hue with the folds like shot silk.
 * - A draped height field (slow, breathing folds) lit from the upper left
 *   with a soft sheen.
 * - The cloth gathers toward the pointer and ripples outward from it.
 *
 * Framework-free so both the page backdrop and the persona swatches can use it.
 */

const VERT = `
attribute vec2 aPos;
void main() { gl_Position = vec4(aPos, 0.0, 1.0); }
`;

const FRAG = `
precision highp float;
uniform vec2  uRes;
uniform float uTime;
uniform vec2  uMouse;     // fabric-space pointer
uniform float uMouseAmt;  // 0..1, eases in when the pointer is over the cloth
uniform vec3  uWarp;
uniform vec3  uWeft;
uniform vec3  uGround;
uniform float uDye;       // how much of the warp/weft colour shows over the ground
uniform float uFold;      // fold depth
uniform float uWeave;     // thread micro-shading strength
uniform float uThread;    // thread width in device px
uniform float uScale;     // folds per screen height
uniform float uScroll;    // parallax offset
uniform float uGrain;

const float PI = 3.14159265;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 3; i++) { v += a * noise(p); p = p * 2.03 + 7.1; a *= 0.5; }
  return v;
}

float height(vec2 p) {
  float t = uTime * 0.11;
  float w = fbm(p * 0.6 + vec2(t, -t * 0.7));
  float folds = sin(p.x * 2.1 + p.y * 0.55 + w * 3.2 + t * 1.4) * 0.55
              + sin(p.x * 3.9 - p.y * 1.25 + w * 2.1 - t * 0.9) * 0.22
              + (fbm(p * 1.7 - t) - 0.5) * 0.35;
  vec2 d = p - uMouse;
  float r2 = dot(d, d);
  float pinch = exp(-r2 * 2.2);
  float ripple = sin(sqrt(r2) * 10.0 - uTime * 2.6) * exp(-r2 * 1.3) * 0.16;
  return (folds - (pinch * 0.75 - ripple) * uMouseAmt) * uFold;
}

void main() {
  vec2 frag = gl_FragCoord.xy;
  float aspect = uRes.x / uRes.y;
  vec2 uv = frag / uRes;
  vec2 p = vec2(uv.x * aspect, uv.y + uScroll) * uScale;

  float e = 0.012;
  float hx = height(p + vec2(e, 0.0)) - height(p - vec2(e, 0.0));
  float hy = height(p + vec2(0.0, e)) - height(p - vec2(0.0, e));
  vec3 n = normalize(vec3(-hx / (2.0 * e), -hy / (2.0 * e), 1.6));

  // plain weave
  vec2 wp = frag / uThread;
  vec2 cell = floor(wp);
  vec2 f = fract(wp);
  float over = mod(cell.x + cell.y, 2.0);          // 1: warp on top
  float across = over > 0.5 ? sin(f.x * PI) : sin(f.y * PI);
  float along  = over > 0.5 ? sin(f.y * PI) : sin(f.x * PI);
  float thread = clamp(across * (0.72 + 0.28 * along), 0.0, 1.0);
  float slub = noise(vec2(over > 0.5 ? cell.x : cell.y, 0.0) * 0.37) * 0.18; // uneven yarn

  // shot fabric: which yarn dominates depends on the fold angle
  float shot = smoothstep(-0.35, 0.35, n.x * 1.8 - n.y * 0.6 + (over - 0.5) * 0.5);
  vec3 yarn = mix(uWeft, uWarp, shot);
  vec3 base = mix(uGround, yarn, uDye);

  vec3 L = normalize(vec3(-0.45, 0.55, 0.75));
  float diff = clamp(dot(n, L), 0.0, 1.0);
  vec3 H = normalize(L + vec3(0.0, 0.0, 1.0));
  float sheen = pow(clamp(dot(n, H), 0.0, 1.0), 28.0);

  // threads narrower than ~2 device px alias into moiré: fade the weave out
  float aa = smoothstep(1.4, 3.2, uThread);
  float micro = mix(1.0, 0.78 + 0.32 * thread - slub, uWeave * aa);
  shot = mix(0.5, shot, aa);
  yarn = mix(uWeft, uWarp, shot);
  base = mix(uGround, yarn, uDye);
  // light the cloth relative to its fold depth so a flat bolt keeps its true colour
  float shade = mix(1.0, 0.62 + 0.5 * diff, clamp(uFold * 1.4, 0.0, 1.0));
  vec3 col = base * shade * micro;
  col += sheen * 0.18 * clamp(uFold * 1.4, 0.0, 1.0) * (0.6 + 0.4 * thread);

  // grain + soft vignette for depth
  col += (hash(frag + fract(uTime)) - 0.5) * uGrain;
  float vig = smoothstep(1.25, 0.35, length((uv - 0.5) * vec2(aspect, 1.0)));
  col *= mix(0.9, 1.0, vig);

  gl_FragColor = vec4(col, 1.0);
}
`;

export interface FabricLook {
  warp: string;
  weft: string;
  ground: string;
  dye: number;
  fold: number;
  weave: number;
  /** thread width in CSS px */
  thread: number;
  scale: number;
  grain: number;
}

export const LINEN: FabricLook = {
  warp: "#F3EEE4",
  weft: "#EAE3D5",
  ground: "#F1ECE2",
  dye: 1,
  fold: 0.3,
  weave: 0.25,
  thread: 2.2,
  scale: 1.3,
  grain: 0.014,
};

function hexToVec(hex: string): [number, number, number] {
  const m = hex.replace("#", "");
  const full = m.length === 3 ? m.split("").map((c) => c + c).join("") : m;
  const n = parseInt(full.slice(0, 6), 16);
  if (Number.isNaN(n)) return [0.9, 0.88, 0.84];
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

interface Options {
  /** Render-resolution multiplier relative to devicePixelRatio (perf). */
  quality?: number;
  /** Follow window scroll for parallax. */
  parallax?: number;
  /** Track the pointer across the whole window instead of just the canvas. */
  windowPointer?: boolean;
}

export interface FabricHandle {
  setLook(look: Partial<FabricLook>): void;
  destroy(): void;
}

export function mountFabric(canvas: HTMLCanvasElement, initial: FabricLook, opts: Options = {}): FabricHandle | null {
  const gl = canvas.getContext("webgl", { antialias: false, alpha: false, premultipliedAlpha: false, powerPreference: "low-power" });
  if (!gl) return null;

  const compile = (type: number, src: string) => {
    const s = gl.createShader(type)!;
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
      console.warn("[fabric]", gl.getShaderInfoLog(s));
      return null;
    }
    return s;
  };
  const vs = compile(gl.VERTEX_SHADER, VERT);
  const fs = compile(gl.FRAGMENT_SHADER, FRAG);
  if (!vs || !fs) return null;
  const prog = gl.createProgram()!;
  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return null;
  gl.useProgram(prog);

  const buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const aPos = gl.getAttribLocation(prog, "aPos");
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

  const u = (name: string) => gl.getUniformLocation(prog, name);
  const U = {
    res: u("uRes"), time: u("uTime"), mouse: u("uMouse"), mouseAmt: u("uMouseAmt"),
    warp: u("uWarp"), weft: u("uWeft"), ground: u("uGround"), dye: u("uDye"),
    fold: u("uFold"), weave: u("uWeave"), thread: u("uThread"), scale: u("uScale"),
    scroll: u("uScroll"), grain: u("uGrain"),
  };

  // current (eased) and target looks
  const cur = {
    warp: hexToVec(initial.warp), weft: hexToVec(initial.weft), ground: hexToVec(initial.ground),
    dye: initial.dye, fold: initial.fold, weave: initial.weave,
  };
  const target = { ...cur, warp: [...cur.warp], weft: [...cur.weft], ground: [...cur.ground] } as typeof cur;
  let thread = initial.thread;
  let scale = initial.scale;
  let grain = initial.grain;

  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const quality = opts.quality ?? 0.6;
  let w = 0, h = 0, dpr = 1;
  let raf = 0;
  let needsFrame = true;
  let visible = true;
  const resize = () => {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2) * quality;
    w = Math.max(1, Math.round(rect.width * dpr));
    h = Math.max(1, Math.round(rect.height * dpr));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w;
      canvas.height = h;
    }
    gl.viewport(0, 0, w, h);
