  { id: "oxide-bath", name: "Oxide bath", description: "A warped colour ramp moves through ink and dye.", look: { ...BASE, pattern: "marble", warp: "#D2402A", weft: "#F0C534", ground: "#24221D", seed: 417, scale: 1.8, dye: .85, speed: .38 } },
  { id: "radial-pleat", name: "Radial pleat", description: "Repeated folds fan out from a movable centre.", look: { ...BASE, pattern: "radial", warp: "#2F55A4", weft: "#A35477", ground: "#EEE5DB", seed: 115, density: .45, speed: .3 } },
];
export const MATERIAL_PALETTES = [
  { name: "Atelier", warp: "#D2402A", weft: "#2F55A4", ground: "#F1ECE2" },
