  await page.getByRole('checkbox',{name:'Show type'}).uncheck();await page.screenshot({path:out+mode+'.png',fullPage:false});
 }
 results.push({check:'Six shader techniques produce distinct frames',pass:true,hashes:seeds});
 await page.getByRole('button',{name:/Thread current/}).click();await pause();await page.getByLabel('Seed',{exact:true}).fill('123');await page.waitForTimeout(500);const seed123=await snap();
 await page.getByLabel('Seed',{exact:true}).fill('124');await page.waitForTimeout(500);assert.notEqual(await snap(),seed123);
 await page.getByLabel('Seed',{exact:true}).fill('123');await page.waitForTimeout(500);assert.equal(await snap(),seed123);results.push({check:'Seeds vary the field and reproduce it exactly while still',pass:true});
 await page.getByRole('button',{name:'Use After hours palette'}).click();await page.waitForTimeout(500);const changed=await snap();assert.notEqual(changed,seed123);
 await page.getByLabel('Colour blending',{exact:true}).selectOption('hue');await page.waitForTimeout(500);assert.notEqual(await snap(),changed);results.push({check:'Palette and hue interpolation visibly change colour',pass:true});
 const hueRange=page.getByLabel('Hue rotation');await hueRange.fill('180');await hueRange.dispatchEvent('input');await page.waitForTimeout(300);assert.notEqual(await snap(),changed);
 await page.getByRole('button',{name:'Resume motion'}).click();await page.getByRole('checkbox',{name:'Let the dyes cycle'}).check();await page.waitForTimeout(600);const moving=await snap();await page.waitForTimeout(800);assert.notEqual(await snap(),moving);results.push({check:'Motion and cycling advance visible material',pass:true});
 await pause();await page.getByRole('checkbox',{name:'Follow pointer & touch'}).check();const box=await preview.boundingBox();await page.mouse.move(box.x+box.width*.7,box.y+box.height*.4);await page.waitForTimeout(1500);const bent=await snap();await page.mouse.move(box.x+box.width*.2,box.y+box.height*.2);await page.waitForTimeout(1500);assert.notEqual(await snap(),bent);results.push({check:'Pointer bends the field while ambient motion is paused',pass:true});
 await page.mouse.click(box.x+box.width*.65,box.y+box.height*.5);const pulse=await snap();await page.waitForTimeout(400);assert.notEqual(await snap(),pulse);results.push({check:'Tap produces an evolving ripple',pass:true});
 await page.getByRole('checkbox',{name:'Follow pointer & touch'}).uncheck();
 const pngPromise=page.waitForEvent('download');await page.getByRole('button',{name:'Export PNG',exact:true}).click();const png=await pngPromise;await png.saveAs(out+'export.png');results.push({check:'PNG export downloads successfully',pass:true,file:png.suggestedFilename()});
 const recipePromise=page.waitForEvent('download');await page.getByRole('button',{name:'Save recipe'}).click();const recipe=await recipePromise;await recipe.saveAs(out+'recipe.json');
 const original=await page.getByLabel('Seed',{exact:true}).inputValue();await page.getByLabel('Seed',{exact:true}).fill('888');await page.locator('input[type=file]').setInputFiles(out+'recipe.json');await page.waitForTimeout(500);assert.equal(await page.getByLabel('Seed',{exact:true}).inputValue(),original);results.push({check:'Recipe export/import restores material',pass:true});
 await page.locator('input[type=file]').setInputFiles({name:'invalid.json',mimeType:'application/json',buffer:Buffer.from('{"version":55}')});assert.match(await page.getByRole('status').innerText(),/version 1/);assert.equal(await page.getByLabel('Seed',{exact:true}).inputValue(),original);
 await page.reload({waitUntil:'networkidle'});await page.waitForTimeout(800);assert.equal(await page.getByLabel('Seed',{exact:true}).inputValue(),original);results.push({check:'Settings survive reload and malformed import leaves settings intact',pass:true});
 await page.getByRole('button',{name:'Use behind Baste'}).click();assert(await page.evaluate(()=>localStorage.getItem('baste:backdrop:v1')));await page.getByRole('button',{name:'Restore original linen'}).click();assert.equal(await page.evaluate(()=>localStorage.getItem('baste:backdrop:v1')),null);results.push({check:'Apply and restore background persist correctly',pass:true});
 await page.emulateMedia({reducedMotion:'reduce'});await page.waitForTimeout(500);assert(await page.getByRole('checkbox',{name:'Follow pointer & touch'}).isDisabled());assert(await page.getByLabel('Motion speed').isDisabled());const reducedA=await snap();await page.waitForTimeout(700);assert.equal(await snap(),reducedA);results.push({check:'Reduced motion freezes animation and disables movement controls',pass:true});
 const noGl=await browser.newContext({viewport:{width:390,height:844},reducedMotion:'reduce'});await noGl.addInitScript(()=>{const original=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(kind,...args){return kind==='webgl'?null:original.call(this,kind,...args)}});const fallback=await noGl.newPage();await fallback.goto('http://127.0.0.1:5211/materials/',{waitUntil:'networkidle'});assert(await fallback.getByRole('button',{name:'Export PNG',exact:true}).isDisabled());assert.equal(await fallback.evaluate(()=>document.documentElement.scrollWidth),390);results.push({check:'No-WebGL fallback and mobile have no overflow',pass:true});await noGl.close();
 assert.deepEqual(errors,[]);
 results.push({check:'No browser or shader errors',pass:true});
} catch(error){results.push({check:'Browser verification',pass:false,error:error.stack});process.exitCode=1;}
finally{await writeFile(out+'interaction-report.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));await browser.close();}
